# Re-enable SysMain (SuperFetch) Service Write-Host "Re-enabling SysMain (SuperFetch) service..." -ForegroundColor Cyan # Set the service to auto start Set-Service -Name "SysMain" -StartupType Automatic -ErrorAction Stop # Start the service Start-Service -Name "SysMain" -ErrorAction SilentlyContinue Write-Host "SysMain service has been re-enabled successfully." -ForegroundColor Green